#[cfg(test)]mod earthquake62_silence64_request_development_tests {
 use super::*;
 const OTHER:u32=0xf1234567;
 fn world()->World {let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}w.learned_skills.clear();w.learned_skills.extend([62,64]);w.hp=Some([1,200]);w.mp=Some([1,200]);let mut a=w.own_actor().unwrap().clone();a.id=OTHER;a.x+=1;a.incarnation+=10;w.actors.insert(OTHER,a);w}
 #[test]fn earthquake_is_selector_only_and_never_predicts_cost_or_targets(){let w=world();let before=serde_json::to_value(&w).unwrap();assert_eq!(request(&w,62,None).unwrap(),vec![20,7,5]);assert!(request(&w,62,Some(OTHER)).is_err());assert_eq!(reuse_millis(62),1500);assert_eq!(serde_json::to_value(&w).unwrap(),before);}
 #[test]fn silence_has_exact_actor_xy_body_and_three_cell_boundary(){let mut w=world();let own=w.own_actor().unwrap().clone();w.actors.get_mut(&OTHER).unwrap().x=own.x+3;let a=&w.actors[&OTHER];let mut b=vec![20,7,7];b.extend(OTHER.to_le_bytes());b.extend(a.x.to_le_bytes());b.extend(a.y.to_le_bytes());assert_eq!(request(&w,64,Some(OTHER)).unwrap(),b);assert_eq!(reuse_millis(64),500);w.actors.get_mut(&OTHER).unwrap().x+=1;assert!(request(&w,64,Some(OTHER)).is_err());assert!(request(&w,64,Some(own.id)).is_err());assert!(request(&w,64,None).is_err());}
 #[test]fn selection_drops_old_target_for_centered_cast_but_never_rebinds_silence_target(){let mut w=world();let mut m=super::super::native_skill_selection::Model::default();m.sync(7,&w,true);let t=super::super::native_skill_selection::Target::capture(&w,OTHER);m.select(Some(62)).unwrap();assert_eq!(m.choice(7,&w,t).unwrap().target,None);m.select(Some(64)).unwrap();assert_eq!(m.choice(7,&w,t).unwrap().target,Some(OTHER));w.actors.get_mut(&OTHER).unwrap().incarnation+=1;assert!(m.choice(7,&w,t).is_err());}
 #[test]fn every_cast_requires_live_book_control_and_positive_mp_without_material_guessing(){for skill in [62,64]{let mut w=world();let target=(skill==64).then_some(OTHER);assert!(request(&w,skill,target).is_ok());w.mp=Some([0,200]);assert!(request(&w,skill,target).is_err());w.mp=Some([1,200]);w.learned_skills.remove(&skill);assert!(request(&w,skill,target).is_err());w.learned_skills.insert(skill);w.accept(&[0x25,2]).unwrap();assert!(request(&w,skill,target).is_err());}}
 #[test]fn silence_effect_does_not_ack_state_or_install_a_local_sixteen_second_lock(){let mut w=world();let before=(w.hp,w.mp,w.movement_blocks.clone());let now=Instant::now();let p=Pending{since:now,casts:w.own_cast_packets,messages:w.message_count,generation:w.generation,incarnation:w.own_actor().unwrap().incarnation};let mut b=vec![0x37];b.extend(OTHER.to_le_bytes());b.extend(2177_u16.to_le_bytes());w.accept(&b).unwrap();assert_eq!(p.observe(&w,now),Feedback::Pending);assert_eq!((w.hp,w.mp,w.movement_blocks.clone()),before);w.message_count+=1;w.last_skill_rejection=Some((w.message_count,280));assert_eq!(p.observe(&w,now),Feedback::Rejected(280));}
 #[test]fn owner_revision_or_dead_target_rejects_the_old_selection_before_request(){let w=world();let mut m=super::super::native_skill_selection::Model::default();m.sync(7,&w,true);m.select(Some(64)).unwrap();let t=super::super::native_skill_selection::Target::capture(&w,OTHER);assert!(m.choice(8,&w,t).is_err());for n in 0..3{let mut w=w.clone();match n{0=>w.generation+=1,1=>w.local_corrections+=1,_=>w.actors.get_mut(&OTHER).unwrap().dead=true};assert!(m.choice(7,&w,t).is_err());}}
}
